INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'reading', 4, 41, 'cloze_passage_shared', 'r1_p4', 41, 'Chỗ trống (1)', NULL, '王明五歲的時候在自己家前面，被(1)帶走了。他最近和朋友說他很(2)，他很希望爸爸知道他大學畢業了。他的朋友聽了以後就上網(3)，最後，王明真的找到他的爸爸了。他爸爸說這些年(4)，沒想到是王明先找到他。他們(5)，也很感謝大家的幫忙。', NULL, '[{"label":"A","text":"想他的爸爸"},{"label":"B","text":"請大家幫忙"},{"label":"C","text":"不認識的人"},{"label":"D","text":"兩人都很高興"},{"label":"E","text":"他不想去找王明"},{"label":"F","text":"他一直在找王明"}]'::jsonb, 2) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'reading', 4, 42, 'cloze_passage_shared', 'r1_p4', 42, 'Chỗ trống (2)', NULL, '王明五歲的時候在自己家前面，被(1)帶走了。他最近和朋友說他很(2)，他很希望爸爸知道他大學畢業了。他的朋友聽了以後就上網(3)，最後，王明真的找到他的爸爸了。他爸爸說這些年(4)，沒想到是王明先找到他。他們(5)，也很感謝大家的幫忙。', NULL, '[{"label":"A","text":"想他的爸爸"},{"label":"B","text":"請大家幫忙"},{"label":"C","text":"不認識的人"},{"label":"D","text":"兩人都很高興"},{"label":"E","text":"他不想去找王明"},{"label":"F","text":"他一直在找王明"}]'::jsonb, 0) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
