INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'reading', 4, 45, 'cloze_passage_shared', 'r1_p4', 45, 'Chỗ trống (5)', NULL, '王明五歲的時候在自己家前面，被(1)帶走了。他最近和朋友說他很(2)，他很希望爸爸知道他大學畢業了。他的朋友聽了以後就上網(3)，最後，王明真的找到他的爸爸了。他爸爸說這些年(4)，沒想到是王明先找到他。他們(5)，也很感謝大家的幫忙。', NULL, '[{"label":"A","text":"想他的爸爸"},{"label":"B","text":"請大家幫忙"},{"label":"C","text":"不認識的人"},{"label":"D","text":"兩人都很高興"},{"label":"E","text":"他不想去找王明"},{"label":"F","text":"他一直在找王明"}]'::jsonb, 3) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'reading', 5, 46, 'passage_mcq', NULL, 46, '為什麼小明不去參加舞會？', NULL, '小明的好朋友問他晚上要不要一起去參加舞會，小明不想去。因為他的感冒才剛好，又加上快考試了，他得讀很多書，而且每天早上也需要去咖啡廳上班。如果晚上還要跟朋友一起出去玩，那就真的太累了。', NULL, '[{"label":"A","text":"因為他生病了"},{"label":"B","text":"因為他想要休息"},{"label":"C","text":"因為他得去工作"},{"label":"D","text":"因為他喜歡在家看書"}]'::jsonb, 1) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'reading', 5, 47, 'passage_mcq', NULL, 47, '為什麼小王覺得考試可能考不好？', NULL, '小王總是非常認真，功課也不錯，但是他因為生病，請了好幾天的假。雖然病一好就馬上讀書，他還是讀不懂中文課本裡的一些句子，而且還有很多語法不了解。明天就要考試了，他非常擔心，現在他也只能希望考試不會太難。', NULL, '[{"label":"A","text":"他本來成績就不好"},{"label":"B","text":"他的身體還沒恢復"},{"label":"C","text":"他準備得還不夠好"},{"label":"D","text":"他聽說考試非常難"}]'::jsonb, 2) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'reading', 5, 48, 'passage_mcq', NULL, 48, '這篇文章告訴我們什麼事？', NULL, '今天小華收到了小美的明信片，明信片裡介紹了日本的食物、天氣和她的學校生活，小美還邀請小華到她家玩、認識她在日本的朋友。小華想了想，雖然她很想去，但是三月臺灣的學校已經開學了，於是她寫了明信片給小美，告訴她雖然那個時間不能去，但是暑假的時候可以去參觀她的學校，到時候再買好吃點心過去。', NULL, '[{"label":"A","text":"小美現在在臺灣"},{"label":"B","text":"小華三月要去日本"},{"label":"C","text":"小美很想吃好吃的點心"},{"label":"D","text":"小華暑假的時候要去找小美"}]'::jsonb, 3) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'reading', 5, 49, 'passage_mcq', NULL, 49, '為什麼小月決定買那條白色的裙子？', NULL, '小月和媽媽去買衣服的時候，看到了一條漂亮的裙子，小月很喜歡那條裙子的樣子，但是太貴了，所以小月想跟媽媽討論以後再決定要不要買。當他們在討論的時候，一位客人看到了小月手上的裙子，就問老闆裙子多少錢，老闆回答了，還說裙子只剩最後這條白色的了，以後也不會再有了。小月聽到老闆說的話以後，馬上買了那條裙子。', NULL, '[{"label":"A","text":"因為小月只喜歡白色的裙子"},{"label":"B","text":"因為那條裙子的價格太便宜了"},{"label":"C","text":"因為以後就買不到那條裙子了"},{"label":"D","text":"因為小月的媽媽要她買那條裙子"}]'::jsonb, 2) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'reading', 5, 50, 'passage_mcq', NULL, 50, '大同為什麼不常回家呢？', NULL, '大同想要給家裡更好的生活，所以從南部北上工作，但是北部的東西太貴了，他週末的時候得在公司加班才能賺更多的錢。雖然賺了很多錢，可是一年才能回家一次，這讓跟家人感情很好的他覺得很傷心。', NULL, '[{"label":"A","text":"他的事情很多"},{"label":"B","text":"他沒有錢回家"},{"label":"C","text":"他跟家人的關係不好"},{"label":"D","text":"他覺得南部東西很貴"}]'::jsonb, 0) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'listening', 1, 1, 'picture_stim_text_choice', NULL, 1, '圖片裡有幾個學生？', '/tocfl/A/listening/1/images/q01_stim.jpg', NULL, '/tocfl/A/listening/1/audio/q01.mp3', '[{"label":"A","text":"三個"},{"label":"B","text":"四個"},{"label":"C","text":"七個"}]'::jsonb, 0) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
