INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'listening', 2, 28, 'dialogue_picture_choice', NULL, 28, '男：小美，你的新家怎麼樣？
女：別說了，我搬到公寓去，結果樓上的小孩經常往下丟垃圾，環境非常髒。', NULL, NULL, '/tocfl/A/listening/1/audio/q28.mp3', '[{"label":"A","imagePath":"/tocfl/A/listening/1/images/q28_A.jpg"},{"label":"B","imagePath":"/tocfl/A/listening/1/images/q28_B.jpg"},{"label":"C","imagePath":"/tocfl/A/listening/1/images/q28_C.jpg"}]'::jsonb, 2) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'listening', 3, 29, 'dialogue_picture_choice', NULL, 29, '男：我們等一下三點在書店門口前見面嗎？
女：我覺得有一點晚，我們可以早半個小時嗎？
男：好啊，那一樣在書店門口前見嗎？
女：對，書店門口見！
男：請問他們幾點見面？', NULL, NULL, '/tocfl/A/listening/1/audio/q29.mp3', '[{"label":"A","imagePath":"/tocfl/A/listening/1/images/q29_A.jpg"},{"label":"B","imagePath":"/tocfl/A/listening/1/images/q29_B.jpg"},{"label":"C","imagePath":"/tocfl/A/listening/1/images/q29_C.jpg"}]'::jsonb, 0) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'listening', 3, 30, 'dialogue_picture_choice', NULL, 30, '男：請問妳要找什麼書？
女：我正在找介紹日本風景的旅遊書。
男：妳看到上面號碼了嗎？如果妳要找日本的書，那在中間2號。
女：謝謝。
男：請問介紹日本風景的書放在哪裡？', NULL, NULL, '/tocfl/A/listening/1/audio/q30.mp3', '[{"label":"A","imagePath":"/tocfl/A/listening/1/images/q30_A.jpg"},{"label":"B","imagePath":"/tocfl/A/listening/1/images/q30_B.jpg"},{"label":"C","imagePath":"/tocfl/A/listening/1/images/q30_C.jpg"}]'::jsonb, 1) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'listening', 3, 31, 'dialogue_picture_choice', NULL, 31, '男：來這家店的人真多。
女：是啊！這家冰淇淋店有很多種味道的冰淇淋。
男：我想吃巧克力和牛奶口味的，我們進去吃吧！
女：好，我請客。
男：請問他們等一下要做什麼？', NULL, NULL, '/tocfl/A/listening/1/audio/q31.mp3', '[{"label":"A","imagePath":"/tocfl/A/listening/1/images/q31_A.jpg"},{"label":"B","imagePath":"/tocfl/A/listening/1/images/q31_B.jpg"},{"label":"C","imagePath":"/tocfl/A/listening/1/images/q31_C.jpg"}]'::jsonb, 2) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'listening', 3, 32, 'dialogue_picture_choice', NULL, 32, '男：照片裡這些人是妳的家人嗎？你們在哪裡拍的？
女：是啊，這是我的爸爸媽媽。這張照片是在船上拍的。
男：這個戴帽子的人是誰？
女：這是我爺爺。他已經七十歲了。
男：請問他們說的是哪一張照片？', NULL, NULL, '/tocfl/A/listening/1/audio/q32.mp3', '[{"label":"A","imagePath":"/tocfl/A/listening/1/images/q32_A.jpg"},{"label":"B","imagePath":"/tocfl/A/listening/1/images/q32_B.jpg"},{"label":"C","imagePath":"/tocfl/A/listening/1/images/q32_C.jpg"}]'::jsonb, 2) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'listening', 3, 33, 'dialogue_picture_choice', NULL, 33, '男：要不要喝點兒啤酒？
女：不行，我等一下要開車。
男：那，喝點兒汽水吧？
女：我還是喝茶好了。
男：請問這位小姐決定喝什麼？', NULL, NULL, '/tocfl/A/listening/1/audio/q33.mp3', '[{"label":"A","imagePath":"/tocfl/A/listening/1/images/q33_A.jpg"},{"label":"B","imagePath":"/tocfl/A/listening/1/images/q33_B.jpg"},{"label":"C","imagePath":"/tocfl/A/listening/1/images/q33_C.jpg"}]'::jsonb, 2) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'listening', 3, 34, 'dialogue_picture_choice', NULL, 34, '男：妳的房間這麼亂，為什麼不整理？
女：我本來上星期日要整理房間，但是我的經理要我去公司。
男：那妳今天看了一個下午的書，為什麼不打掃？
女：好啦！我明天會整理。
男：請問這位小姐明天打算做什麼？', NULL, NULL, '/tocfl/A/listening/1/audio/q34.mp3', '[{"label":"A","imagePath":"/tocfl/A/listening/1/images/q34_A.jpg"},{"label":"B","imagePath":"/tocfl/A/listening/1/images/q34_B.jpg"},{"label":"C","imagePath":"/tocfl/A/listening/1/images/q34_C.jpg"}]'::jsonb, 0) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'listening', 3, 35, 'dialogue_picture_choice', NULL, 35, '男：這裡的天氣怎麼樣？
女：冬天太冷，夏天太熱。
男：那麼春天呢？
女：常常下雨。
男：請問這裡的春天常常怎麼樣？', NULL, NULL, '/tocfl/A/listening/1/audio/q35.mp3', '[{"label":"A","imagePath":"/tocfl/A/listening/1/images/q35_A.jpg"},{"label":"B","imagePath":"/tocfl/A/listening/1/images/q35_B.jpg"},{"label":"C","imagePath":"/tocfl/A/listening/1/images/q35_C.jpg"}]'::jsonb, 2) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'listening', 3, 36, 'dialogue_picture_choice', NULL, 36, '男：我想找王先生。
女：請問您和他約好了嗎？
男：沒有。是他要我來找他的。
女：您先留下您的電話，我會請王先生打電話給您。
男：請問這位小姐要這位先生做什麼？', NULL, NULL, '/tocfl/A/listening/1/audio/q36.mp3', '[{"label":"A","imagePath":"/tocfl/A/listening/1/images/q36_A.jpg"},{"label":"B","imagePath":"/tocfl/A/listening/1/images/q36_B.jpg"},{"label":"C","imagePath":"/tocfl/A/listening/1/images/q36_C.jpg"}]'::jsonb, 2) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'listening', 3, 37, 'dialogue_picture_choice', NULL, 37, '男：小春的生日快到了，我們一起送他禮物，怎麼樣？
女：好啊！他喜歡畫畫，我們可以送他畫畫用的筆。
男：嗯，還可以送他放筆的袋子。
女：好啊，今天下課以後我們一起去買禮物吧。
男：請問他們決定送什麼？', NULL, NULL, '/tocfl/A/listening/1/audio/q37.mp3', '[{"label":"A","imagePath":"/tocfl/A/listening/1/images/q37_A.jpg"},{"label":"B","imagePath":"/tocfl/A/listening/1/images/q37_B.jpg"},{"label":"C","imagePath":"/tocfl/A/listening/1/images/q37_C.jpg"}]'::jsonb, 0) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'listening', 3, 38, 'dialogue_picture_choice', NULL, 38, '男：妳看電視新聞了嗎？有一個很可怕的消息。
女：什麼可怕的消息？
男：妳快點開電視，我剛剛才看到的。
女：我上網看過新聞了，可是沒看到什麼可怕的消息。
男：請問這位先生從哪裡知道可怕的消息？', NULL, NULL, '/tocfl/A/listening/1/audio/q38.mp3', '[{"label":"A","imagePath":"/tocfl/A/listening/1/images/q38_A.jpg"},{"label":"B","imagePath":"/tocfl/A/listening/1/images/q38_B.jpg"},{"label":"C","imagePath":"/tocfl/A/listening/1/images/q38_C.jpg"}]'::jsonb, 1) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'listening', 3, 39, 'dialogue_picture_choice', NULL, 39, '男：妳想吃什麼?
女：聽說這裡的北京烤鴨很好吃。
男：我們點一隻烤鴨，一碗酸辣湯，怎麼樣？
女：再點一個糖醋魚吧！
男：請問他們應該在什麼地方？', NULL, NULL, '/tocfl/A/listening/1/audio/q39.mp3', '[{"label":"A","imagePath":"/tocfl/A/listening/1/images/q39_A.jpg"},{"label":"B","imagePath":"/tocfl/A/listening/1/images/q39_B.jpg"},{"label":"C","imagePath":"/tocfl/A/listening/1/images/q39_C.jpg"}]'::jsonb, 1) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'listening', 3, 40, 'dialogue_picture_choice', NULL, 40, '男：已經很晚了，妳怎麼還在這裡？
女：經理說明天要和他一起討論，我今天一定要準備好。
男：我不放心妳一個人回家，還是等會兒我開車送妳回去。
女：謝謝你！但是我今天晚上打算睡在公司裡。
男：請問這位小姐今天晚上打算做什麼？', NULL, NULL, '/tocfl/A/listening/1/audio/q40.mp3', '[{"label":"A","imagePath":"/tocfl/A/listening/1/images/q40_A.jpg"},{"label":"B","imagePath":"/tocfl/A/listening/1/images/q40_B.jpg"},{"label":"C","imagePath":"/tocfl/A/listening/1/images/q40_C.jpg"}]'::jsonb, 1) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'listening', 4, 41, 'dialogue_text_choice', NULL, 41, '男：我昨天運動了一整天。
女：你看你，累到說不了話了？
男：喔，不是因為運動，是因為我早上五點就起床了，所以想睡覺。
女：你這樣沒辦法上班，我幫你請假，你快回去睡吧！
男：請問這位小姐為什麼要幫這位先生請假？', NULL, NULL, '/tocfl/A/listening/1/audio/q41.mp3', '[{"label":"A","text":"因為他想睡覺"},{"label":"B","text":"因為他想運動"},{"label":"C","text":"因為他不想上班"},{"label":"D","text":"因為他起不了床"}]'::jsonb, 0) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'listening', 4, 42, 'dialogue_text_choice', NULL, 42, '男：妳上個禮拜的旅行怎麼樣？
女：還不錯。交通方便、風景漂亮，我想去的地方都去了。
男：那真是個開心的旅行。
女：嗯，雖然每件事都不錯，但是我回國的時候，把錢包掉在旅館了。
男：關於這位小姐，下面哪一個是對的？', NULL, NULL, '/tocfl/A/listening/1/audio/q42.mp3', '[{"label":"A","text":"她旅行時不小心掉了東西"},{"label":"B","text":"她旅行時有些想去的地方沒去"},{"label":"C","text":"她覺得旅行時最麻煩的是交通"},{"label":"D","text":"她覺得旅行最重要的是風景漂亮"}]'::jsonb, 0) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'listening', 4, 43, 'dialogue_text_choice', NULL, 43, '男：妳怎麼了？好像不太開心的樣子。
女：我沒事，我每次考試的時候就會這樣。
男：可是昨天不是已經考完了嗎？
女：是啊，可是我很擔心沒考好。
男：這位小姐為什麼不開心？', NULL, NULL, '/tocfl/A/listening/1/audio/q43.mp3', '[{"label":"A","text":"她怕考得不好"},{"label":"B","text":"她的成績不好"},{"label":"C","text":"她沒參加考試"},{"label":"D","text":"她怕題目寫不完"}]'::jsonb, 0) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'listening', 4, 44, 'dialogue_text_choice', NULL, 44, '女：王先生嗎？您好，我是住在您家樓下的陳太太。
男：請問有什麼事嗎？
女：我總是聽到您走路的聲音，有時還聽到您與女朋友大聲地講話。我找您好幾次了，可是您都不在家。
男：啊！不好意思，不好意思，我會注意的。
女：陳太太為什麼找王先生？', NULL, NULL, '/tocfl/A/listening/1/audio/q44.mp3', '[{"label":"A","text":"想請他搬家"},{"label":"B","text":"想請他吃飯"},{"label":"C","text":"介紹女朋友給他"},{"label":"D","text":"請他注意聲音的大小"}]'::jsonb, 3) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'listening', 4, 45, 'dialogue_text_choice', NULL, 45, '男：妳昨天怎麼那麼晚才睡？
女：我昨天十二點多睡的，我不覺得晚啊！
男：都半夜了，還不晚？這麼晚才睡覺對身體很不好。
女：還好吧？我一直都是這個時間睡覺，也沒生什麼病。
女：請問這位小姐的意思是什麼？', NULL, NULL, '/tocfl/A/listening/1/audio/q45.mp3', '[{"label":"A","text":"她習慣在不同的時間睡覺"},{"label":"B","text":"她每天都是這個時間起床"},{"label":"C","text":"她認為睡覺對健康有影響"},{"label":"D","text":"她不覺得自己很晚才睡覺"}]'::jsonb, 3) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'listening', 4, 46, 'dialogue_text_choice', NULL, 46, '男：夏天到了，我們明天去海邊吧！
女：好啊！你覺得我應該穿短裙好呢？還是短褲好呢？
男：我覺得妳應該穿短褲，因為我們要在沙灘上打球。
女：好啊，明天見。
女：請問這位先生說了什麼？', NULL, NULL, '/tocfl/A/listening/1/audio/q46.mp3', '[{"label":"A","text":"他剛從海邊回來"},{"label":"B","text":"他喜歡夏天去海邊玩"},{"label":"C","text":"他給這位小姐買了褲子"},{"label":"D","text":"他約了這位小姐明天去運動"}]'::jsonb, 3) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'listening', 4, 47, 'dialogue_text_choice', NULL, 47, '男：為了妳的生日，我想請妳吃蛋糕。
女：你人來我就很開心了，蛋糕，我來準備就好了。
男：這是為了感謝妳請我參加明天的生日舞會，或是妳有更想要的禮物嗎？
女：你太客氣了。吃蛋糕和收禮物都不是最重要的事。
女：請問這位小姐的意思是什麼？', NULL, NULL, '/tocfl/A/listening/1/audio/q47.mp3', '[{"label":"A","text":"她不想請這位先生吃蛋糕"},{"label":"B","text":"她想幫這位先生慶祝生日"},{"label":"C","text":"她要朋友來參加舞會就好"},{"label":"D","text":"她想要大家一起唱生日歌"}]'::jsonb, 2) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'listening', 4, 48, 'dialogue_text_choice', NULL, 48, '男：我要去逛百貨公司，要一起嗎？
女：我最近花了太多錢了，還是不要吧。
男：最近百貨公司有活動，很多商品不但很便宜，還會給很多試用的東西。
女：喔，有不用花錢的啊！那我們快走吧！
女：為什麼這位小姐想去百貨公司？', NULL, NULL, '/tocfl/A/listening/1/audio/q48.mp3', '[{"label":"A","text":"她想拿商店送的東西"},{"label":"B","text":"她最近很想花錢買東西"},{"label":"C","text":"她想要這位先生送她禮物"},{"label":"D","text":"她想和這位先生一起去逛街"}]'::jsonb, 0) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'listening', 4, 49, 'dialogue_text_choice', NULL, 49, '男：今天天氣好熱，我們在家吹冷氣多好，還是不要去買衣服了。
女：不行，你昨天答應我今天要出門買衣服。
男：可是妳沒發現衣服已經很多了嗎？
女：我覺得，你只是怕太晚回家，沒辦法看棒球比賽！
女：請問下面哪一個是對的？', NULL, NULL, '/tocfl/A/listening/1/audio/q49.mp3', '[{"label":"A","text":"這位先生今天想留在家裡"},{"label":"B","text":"這位小姐怕自己太晚回家"},{"label":"C","text":"他們兩人今天都想看棒球比賽"},{"label":"D","text":"他們已經買完衣服回家休息了"}]'::jsonb, 0) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 1), 'listening', 4, 50, 'dialogue_text_choice', NULL, 50, '男：小姐，這是昨天跟你們買的牛奶，味道有點奇怪，我想換一瓶新的。
女：請問您帶了發票嗎？
男：喔，我沒帶來。
女：我們要看到發票，才能換東西，不好意思。
女：這位小姐的意思是什麼？', NULL, NULL, '/tocfl/A/listening/1/audio/q50.mp3', '[{"label":"A","text":"她要把錢還給客人"},{"label":"B","text":"東西賣出去就不能換了"},{"label":"C","text":"她沒有東西可以換給客人"},{"label":"D","text":"沒有發票，就不能換東西"}]'::jsonb, 3) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;